import { chromium } from "playwright-core";
import { pathToFileURL } from "node:url";
import path from "node:path";

const root = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const usability = path.join(root, "usability");
const chrome = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";

const browser = await chromium.launch({ executablePath: chrome, headless: true });

async function measure(page) {
  return page.evaluate(() => {
    const sel = document.getElementById("traceSelect");
    const r = sel.getBoundingClientRect();
    const cs = getComputedStyle(sel);
    return {
      innerWidth: window.innerWidth,
      scrollWidth: document.documentElement.scrollWidth,
      clientWidth: document.documentElement.clientWidth,
      bodyScrollWidth: document.body.scrollWidth,
      select: {
        className: sel.className,
        x: Math.round(r.x * 10) / 10,
        y: Math.round(r.y * 10) / 10,
        width: Math.round(r.width * 10) / 10,
        height: Math.round(r.height * 10) / 10,
        cssWidth: cs.width,
        cssMaxWidth: cs.maxWidth,
        cssPadding: cs.padding,
        cssPosition: cs.position,
        cssClip: cs.clip,
        display: cs.display,
      },
      triggerDisplay: getComputedStyle(document.getElementById("preloadedTrigger")).display,
    };
  });
}

const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
await mobile.goto(pathToFileURL(path.join(root, "index.html")).href, { waitUntil: "domcontentloaded" });
await mobile.waitForTimeout(400);
const mobileInfo = await measure(mobile);
await mobile.screenshot({ path: path.join(usability, "mobile-select-overflow-live.png"), fullPage: true });

const desktop = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
await desktop.goto(pathToFileURL(path.join(root, "index.html")).href, { waitUntil: "domcontentloaded" });
await desktop.waitForTimeout(400);
const desktopInfo = await measure(desktop);

const fixture = await browser.newPage({ viewport: { width: 430, height: 720 }, deviceScaleFactor: 1 });
await fixture.goto(pathToFileURL(path.join(usability, "mobile-select-overflow.html")).href, { waitUntil: "domcontentloaded" });
await fixture.waitForTimeout(200);
await fixture.screenshot({ path: path.join(usability, "mobile-select-overflow.png"), fullPage: true });

console.log(JSON.stringify({ mobileInfo, desktopInfo }, null, 2));
await browser.close();
EOF
