import { chromium } from "playwright-core";
import { pathToFileURL } from "node:url";

const chrome = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
const browser = await chromium.launch({ executablePath: chrome, headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
await page.goto(pathToFileURL("/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web/index.html").href, { waitUntil: "domcontentloaded" });
await page.waitForTimeout(400);
const offenders = await page.evaluate(() => {
  const vw = window.innerWidth;
  return [...document.querySelectorAll("*")].flatMap((el) => {
    const r = el.getBoundingClientRect();
    const right = r.x + r.width;
    if (r.width <= 1 || r.height <= 0) return [];
    if (right <= vw + 1) return [];
    return [{
      tag: el.tagName.toLowerCase(),
      id: el.id,
      className: String(el.className).slice(0, 80),
      x: Math.round(r.x),
      width: Math.round(r.width),
      right: Math.round(right),
    }];
  });
});
console.log(JSON.stringify({ scrollWidth: await page.evaluate(() => document.documentElement.scrollWidth), offenders }, null, 2));
await browser.close();
EOF
